/**
 * @name Command injection via subprocess
 * @description Using subprocess with unsanitized input can lead to command injection
 * @kind path-problem
 * @problem.severity error
 * @id py/command-injection-dateutil
 * @tags security
 *        external/cwe/cwe-078
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.dataflow.new.RemoteFlowSources
import semmle.python.Concepts

module CommandInjectionConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof RemoteFlowSource
  }

  predicate isSink(DataFlow::Node sink) {
    exists(SystemCommandExecution cmd |
      sink = cmd.getCommand()
    )
  }
}

module CommandInjectionFlow = TaintTracking::Global<CommandInjectionConfig>;
import CommandInjectionFlow::PathGraph

from CommandInjectionFlow::PathNode source, CommandInjectionFlow::PathNode sink
where CommandInjectionFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Command injection from $@.", source.getNode(), "user input"

/**
 * @name Path traversal via tarfile extraction
 * @description Extracting tarfiles without validating member paths can lead to path traversal
 * @kind path-problem
 * @problem.severity error
 * @id py/tarfile-path-traversal
 * @tags security
 *        external/cwe/cwe-022
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.ApiGraphs

module TarfileConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    exists(DataFlow::CallCfgNode call |
      call = API::moduleImport("tarfile").getMember("open").getACall() and
      source = call
    )
  }

  predicate isSink(DataFlow::Node sink) {
    exists(DataFlow::CallCfgNode call |
      call.getFunction().(DataFlow::AttrRead).getAttributeName() in ["extract", "extractall"] and
      sink = call.getFunction().(DataFlow::AttrRead).getObject()
    )
  }
}

module TarfileFlow = TaintTracking::Global<TarfileConfig>;
import TarfileFlow::PathGraph

from TarfileFlow::PathNode source, TarfileFlow::PathNode sink
where TarfileFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Tarfile extraction without path validation from $@.", source.getNode(), "tarfile"
